#!/usr/bin/env python3
# Разовая правка PLAN.md по ответам пользователя: Inter, элементы только там, где они есть, служебные плашки — оформление существующих.
p = '../PLAN.md'
s = open(p, encoding='utf-8').read()

a = s.index('| 1 | **Шрифт.**')
b = s.index('| 3 | **Настройки стекла.**')
new = '''| 1 | **Шрифт.** | **Решено: Inter.** В макетах DM Sans не нёс кириллицу (русский текст рисовался системным шрифтом), поэтому макеты переведены на Inter — теперь они показывают то, что получится в клиентах. Inter уже вшит в клиенты, менять шрифт не нужно. |
| 2 | **Элементы, которые есть не во всех клиентах.** | **Решено:** оформление переносим в каждый клиент только для тех элементов, которые в нём уже есть как функция. Новых функций ради макета не делаем. Известное: блок аккаунтов в баре — только Electron (в веб клиенте нет); в `/m` «Записей» нет — их из переноса исключаем (в макете остались как пример, при приёмке этапа 1 не проверяются); «Скрыть панель» и «Высокая доступность» на входе — только Electron; ссылка на видеозвонок в меню шапки — там, где у пользователя есть право (`can_call_links`). На старте каждого этапа составляется список «есть / нет» по клиенту, приёмка идёт только по тому, что есть. |
'''
s = s[:a] + new + s[b:]

s = s.replace('служебные уведомления в ленте (добавление, объявление), разделитель «Непрочитанные сообщения».', 'служебные уведомления в ленте.')
s = s.replace('''1. **Шрифт**: решение 1 из раздела 1; `woff2` в `server/src/public/shared/fonts` и `client/src/assets/fonts`, `font-display: swap`, проверить метрики строк (высоты строк списка не должны «поплыть»).''',
 '''1. **Шрифт**: Inter (уже вшит: `server/src/public/shared/fonts`, `client/src/assets/fonts`). Менять файлы не нужно; в токене `--ff` убрать лишние запасные шрифты, оставить `Inter, -apple-system, system-ui, sans-serif`. Высоты строк в макетах уже сняты с Inter.''')
s = s.replace('| Шрифт без кириллицы | Решение 1 до начала |\n', '')
s = s.replace('| Макет показывает то, чего нет в клиенте (аккаунты в `/m`, «Звонки», служебные плашки) | Решение 2 на старте этапа |',
              '| Макет показывает то, чего нет в клиенте (аккаунты в `/m` и вебе, страница «Звонки» в `/m`) | Решение 2: переносим только существующее, список «есть / нет» на старте этапа |')
s = s.replace('служебные (добавление, объявление), «Непрочитанные сообщения», «печатает…» (текст в шапке)', 'служебные уведомления в ленте — оформление уже существующих системных сообщений клиента (добавление и удаление участника, объявление), «Непрочитанные сообщения», «печатает…» (текст в шапке)')
s = s.replace('**1.3 Список чатов.** Единая плоская сплошная шапка (заголовок, кнопка, поиск, папки-чипы; список под ней не просвечивает); строки (`.row`), закрепление, отключение звука, непрочитанные, статусы-галочки; пространства (`spaceSheet`), переключатель записей (если решение 2 «делаем»: плитки как у папок, круглое выделение на 46 px при аватарке 36); комната и темы;',
              '**1.3 Список чатов.** Единая плоская сплошная шапка (заголовок, кнопка, поиск, папки-чипы; список под ней не просвечивает); строки (`.row`), закрепление, отключение звука, непрочитанные, статусы-галочки; пространства (`spaceSheet`); комната и темы;')
s = s.replace('**2.1 Каркас.** Окно: фон, отступы 10, сайдбар и чат как карточки (радиус 22); бар слева (пространства, папки, **аккаунты — по решению 2**, выбор круглый 46 px, значок папки цветом папки);',
              '**2.1 Каркас.** Окно: фон, отступы 10, сайдбар и чат как карточки (радиус 22); бар слева (пространства, папки, значок папки цветом папки; блока аккаунтов в веб клиенте нет — не переносится);')
s = s.replace('бар с аккаунтами (если есть в Electron), экран входа', 'бар с аккаунтами (есть только в Electron: плитки как у папок, круглое выделение 46 px при аватарке 36, точка присутствия, счётчик), экран входа')
s = s.replace('**Мобильный (`mobile.html`):** чаты, переписка, комната, контакты, настройки, меню сообщения, реакции, все реакции, смайлы, меню чата, меню шапки, меню «+», папки, пространства, записи, профиль',
              '**Мобильный (`mobile.html`):** чаты, переписка, комната, контакты, настройки, меню сообщения, реакции, все реакции, смайлы, меню чата, меню шапки, меню «+», папки, пространства, записи (только пример, в `/m` нет), профиль')
open(p, 'w', encoding='utf-8').write(s)
print('ok')
